            return year > d.year;
        if (month != d.month)
            return month > d.month;
        return day > d.day;
    }

    bool operator==(const Date& d) const {
        return (year == d.year && month == d.month && day == d.day);
    }

    void print() const {
        std::cout << day << "/" << month << "/" << year << std::endl;
    }
};

