function hasCycle(head) {
    if (head === null || head.next === null) {
        return false;
    }

    let slow = head;
    let fast = head.next;

    while (slow !== fast) {
        if (fast === null || fast.next === null) {
            return false;
        }
        slow = slow.next;
        fast = fast.next.next;
    }

    return true;
}
```

This function uses the Floyd's Tortoise and Hare algorithm to detect a cycle in a linked list. If a cycle exists, the fast pointer will eventually meet the slow pointer. If there is no cycle, the fast pointer will reach the end of the list.

