def number_to_words(num):
    below_20 = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", 
                "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", 
                "Eighteen", "Nineteen"]
    tens_multiple = ["", "Ten", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]
    thousands = ["", "Thousand", "Million", "Billion"]

    def recursive_convert(num):
        if num == 0:
            return ""
        elif num < 20:
            return below_20[num] + " "
        elif num < 100:
            return tens_multiple[num // 10] + " " + recursive_convert(num % 10)
        else:
            return below_20[num // 100] + " Hundred " + recursive_convert(num % 100)

    words = ""
    i = 0
    while num > 0:
        if num % 1000 != 0:
            words = recursive_convert(num % 1000) + thousands[i] + " " + words
        num //= 1000
        i += 1

    return words.strip()

# Example usage:
print(number_to_words(12345))
