```java
import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.input.KeyEvent;
import javafx.scene.layout.Pane;
import javafx.scene.shape.Rectangle;
import javafx.stage.Stage;

public class MoveSquare extends Application {
    private static final int SQR_SIZE = 50;
    private Rectangle rect;
    private double x = 50, y = 50;

    @Override
    public void start(Stage primaryStage) {
        rect = new Rectangle(x, y, SQR_SIZE, SQR_SIZE);
        Pane root = new Pane(rect);

        Scene scene = new Scene(root, 300, 300);
        primaryStage.setTitle("Move Square");
        primaryStage.setScene(scene);
        primaryStage.show();

        scene.setOnKeyPressed(e -> {
            switch (e.getCode()) {
                case UP:
                    y -= 10;
                    break;
                case DOWN:
                    y += 10;
                    break;
                case LEFT:
                    x -= 10;
                    break;
                case RIGHT:
                    x += 10;
                    break;
            }
            rect.setLayoutX(x);
            rect.setLayoutY(y);
        });
    }

    public static void main(String[] args) {
        launch(args);
    }
}
```

This JavaFX application creates a window with a square that can be moved around using the arrow keys. The square's position is updated based on the key pressed and then the square's layout coordinates are adjusted accordingly.

